UPDATE ord_mainSET rst_ind_comment_info = (  SELECT  case when jsonb_agg ( sub.elems )  is not null  then jsonb_agg ( sub.elems )  else NULL  end  FROM  (  SELECT  elem AS elems  FROM  jsonb_array_elements ( rst_ind_comment_info ) AS elem  WHERE elem ? 'no'  ) AS sub  )WHERE  EXISTS ( SELECT 1 FROM jsonb_array_elements ( rst_ind_comment_info ) AS item WHERE not (item  ? 'no') )